"function wavFromFloat(samples){const buf=new ArrayBuffer(44+samples.length*2),v=new DataView(buf);const ascii=(o,s)=>{for(let i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i));};ascii(0,'RIFF');v.setUint32(4,36+samples.length*2,true);ascii(8,'WAVE');ascii(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,16000,true);v.setUint32(28,32000,true);v.setUint16(32,2,true);v.setUint16(34,16,true);ascii(36,'data');v.setUint32(40,samples.length*2,true);let o=44;for(let i=0;i<samples.length;i++,o+=2){let x=Math.max(-1,Math.min(1,samples[i]));v.setInt16(o,x<0?x*32768:x*32767,true);}return new Blob([buf],{type:'audio/wav'});}\n"
"function enqueueTalk(samples){if(!samples.length)return;if(talkQueue.length>=3){talkQueue.shift();talkDrops++;}talkQueue.push(wavFromFloat(samples));pumpTalk();}\n"
"async function pumpTalk(){if(talkSending)return;talkSending=true;while(talkQueue.length){const blob=talkQueue.shift();try{const r=await fetch('/audio',{method:'POST',headers:{'Content-Type':'audio/wav','X-JrBot-Audio':'1'},body:blob});if(!r.ok)throw Error(await r.text());}catch(e){setState('Falha enviando voz ao JrBot: '+e.message);break;}}talkSending=false;}\n"
"function flushTalkSamples(force){const target=12000;while(talkSamples.length>=target||(force&&talkSamples.length)){const count=talkSamples.length>=target?target:talkSamples.length;const out=new Float32Array(count);for(let i=0;i<count;i++)out[i]=talkSamples[i];talkSamples.splice(0,count);enqueueTalk(out);}}\n"
"async function startTalk(ev){if(ev){ev.preventDefault();try{ev.currentTarget.setPointerCapture(ev.pointerId);}catch(_){}}if(talkRequested)return;talkRequested=true;resumeListenAfterTalk=listenWanted;if(resumeListenAfterTalk&&liveAudioLog.length)liveLogAdd('PTT_START');q('v16-ptt').classList.add('active');q('v16-ptt').textContent='FALANDO... SOLTE PARA OUVIR';setState('Preparando microfone do celular...');try{const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});if(!talkRequested){stream.getTracks().forEach(t=>t.stop());return;}talkStream=stream;if(resumeListenAfterTalk)await stopListen();const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('AudioContext indisponível.');talkCtx=new AC();await talkCtx.resume();talkSource=talkCtx.createMediaStreamSource(stream);talkNode=talkCtx.createScriptProcessor(4096,1,1);talkGain=talkCtx.createGain();talkGain.gain.value=0;talkNode.onaudioprocess=e=>{if(!talkRequested)return;const d=downsample(e.inputBuffer.getChannelData(0),talkCtx.sampleRate);for(let i=0;i<d.length;i++)talkSamples.push(d[i]);flushTalkSamples(false);};talkSource.connect(talkNode);talkNode.connect(talkGain);talkGain.connect(talkCtx.destination);talkActive=true;talkDrops=0;setState('Falando no JrBot. Solte o botão para voltar a ouvir.');}catch(e){talkRequested=false;talkActive=false;q('v16-ptt').classList.remove('active');q('v16-ptt').textContent='SEGURE PARA FALAR NO JRBOT';if(talkStream)talkStream.getTracks().forEach(t=>t.stop());talkStream=null;feedback('Microfone do celular indisponível: '+e.message,true);if(resumeListenAfterTalk)startListen(true);}}\n"
"async function stopTalk(ev){if(ev)ev.preventDefault();if(!talkRequested&&!talkActive)return;talkRequested=false;if(talkNode){talkNode.onaudioprocess=null;try{talkSource.disconnect();talkNode.disconnect();talkGain.disconnect();}catch(_){}}if(talkStream)talkStream.getTracks().forEach(t=>t.stop());talkStream=null;flushTalkSamples(true);talkSamples=[];talkActive=false;q('v16-ptt').classList.remove('active');q('v16-ptt').textContent='SEGURE PARA FALAR NO JRBOT';setState('Finalizando envio da fala...');while(talkSending||talkQueue.length)await sleep(40);if(liveAudioLog.length)liveLogAdd('PTT_STOP drops='+talkDrops);setState(talkDrops?'Fala concluída. Blocos descartados por atraso: '+talkDrops+'.':'Fala concluída.');if(talkCtx){try{await talkCtx.close();}catch(_){}talkCtx=null;}if(resumeListenAfterTalk){resumeListenAfterTalk=false;try{await startListen(true);}catch(e){setState('Fala concluída; não foi possível retomar áudio: '+e.message);}}}\n"
"function build(){injectStyle();setupCameraStage();try{const saved=Number(localStorage.getItem('jrbot.camera.rotation'));if([0,90,180,270].includes(saved))cameraRotationDeg=saved;}catch(_){}const sub=document.querySelector('.top .sub');if(sub)sub.textContent='LAB · JrBot_V1.7_V2_01.1';const card=q('cam-btn')&&q('cam-btn').closest('.card');if(!card)return;const tools=document.createElement('div');tools.className='v16-tools';tools.innerHTML=\"<div class='row'><label>Foto</label><select id='v16-photo-size'><option value='vga'>640x480 · VGA</option><option value='svga'>800x600 · SVGA</option><option value='xga' selected>1024x768 · XGA</option><option value='hd'>1280x720 · HD</option><option value='uxga'>1600x1200 · UXGA</option></select><select id='v16-photo-quality'><option value='20'>Econômica</option><option value='12' selected>Normal</option><option value='8'>Alta</option></select></div><div class='row'><label>Rotação câmera</label><select id='v16-camera-rotation'><option value='0'>0°</option><option value='90'>+90°</option><option value='180'>180°</option><option value='270'>-90°</option></select></div><div class='v16-livebar'><label>Ao vivo WebRTC</label><select id='v16-live-size'><option value='fast'>320x240 · rápido</option><option value='balanced' selected>640x480 · equilibrado</option><option value='quality'>800x600 · qualidade</option></select><button id='v16-live' class='grow'>Iniciar ao vivo</button></div><div id='v16-live-meta' class='v16-meta'>Live parado. Rotação selecionada: \"+cameraRotationLabel()+\"°.</div><div class='v16-tools'><div class='v16-meta'>Vídeo JPEG via DataChannel + áudio PCMA full-duplex na mesma sessão WebRTC.</div><div class='row'><button id='v16-mute-cell' class='grow' disabled>Mutar microfone do celular</button><button id='v16-mute-jrbot' class='grow' disabled>Mutar áudio do JrBot</button></div><div id='v16-memory' class='v16-meta'>Memória: aguardando leitura...</div><button id='v16-log' class='grow'>Baixar log Live</button><div id='v16-state' class='v16-meta'>Live parado.</div><audio id='v16-webrtc-audio' autoplay playsinline style='display:none'></audio></div>\";card.appendChild(tools);const rot=q('v16-camera-rotation');rot.value=String(cameraRotation());rot.onchange=()=>setCameraRotation(rot.value);q('cam-btn').onclick=capturePhoto;q('v16-live').onclick=toggleLive;q('v16-mute-cell').onclick=toggleCellMic;q('v16-mute-jrbot').onclick=toggleJrBotAudio;q('v16-log').onclick=downloadLiveLog;window.addEventListener('beforeunload',()=>{live=false;stopWebRtc(false);if(v16CamUrl)URL.revokeObjectURL(v16CamUrl);if(v16SaveUrl)URL.revokeObjectURL(v16SaveUrl);});const foot=document.querySelector('.foot');if(foot)foot.textContent='Laboratório JrBot: vídeo JPEG DataChannel + áudio WebRTC + monitor de memória.';}\n"
"if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',build);else build();\n"
"})();\n";
